VALUES('a67f2619-16cf-47dd-a0bd-d213d53d6c1f','news.bloomberg-latest','00e66885-5cad-48bd-a637-9123c07365ab',1,'validated','[]'::jsonb,'[{"fact_type":"news.bloomberg_latest_stories","subject_role":"subject","cardinality":"one"}]'::jsonb,'{}'::jsonb,'{"id":"phx-latest"}'::jsonb,'{"base":"$","produces":{"news.bloomberg_latest_stories":{"path":"$"}}}'::jsonb,'one',1,'{}','{}','read','per_call',300,'{"data":{"title":"Latest News & Updates: Breaking News, Headlines Today","modules":[{"id":"filter_latest","type":"lineup_content","title":null,"stories":[{"id":"2026-09-14/ai-data-center-boom-is-changing-cmbs-risks","type":"article","internalID":"TJZGDVKK3NYA00","title":"Wall Street’s Data Center Boom Is Reshaping the Real Estate Bond Market","autoGeneratedSummary":"The commercial mortgage backed securities market, long a mainstay of financing for America’s offices, apartments and malls, is being reshaped by a surge in data-center deals, forcing investors to grapple with an entirely new set of risks.","published":1789380600,"updatedAt":1789380600,"byline":"Eliza Ronalds-Hannon and Scott Carpenter","longURL":"https://www.bloomberg.com/news/articles/2026-09-14/ai-data-center-boom-is-changing-cmbs-risks","primaryCategory":"Markets","wordCount":1201,"premium":false},{"id":"2026-09-14/argentina-s-ypf-says-close-to-signing-more-lng-sales-contracts","type":"article","internalID":"TLCJWRKK3NY900","title":"Argentina’s YPF Says Close to Signing More LNG Sales Contracts","autoGeneratedSummary":"Argentina’s state-run YPF SA is close to signing several liquefied natural gas sales contracts for a proposed $24 billion export plant, its chief executive said on Monday, a key step toward a green light for the facility.","published":1789380484,"updatedAt":1789380484,"byline":"Stephen Stapczynski","longURL":"https://www.bloomberg.com/news/articles/2026-09-14/argentina-s-ypf-says-close-to-signing-more-lng-sales-contracts","primaryCategory":null,"wordCount":214,"premium":false},{"id":"2026-09-14/warsh-and-the-fed-need-clarity-more-than-certainty","type":"article","internalID":"TLCMG4KGCTFK00","title":"Warsh and the Fed Need Clarity More Than Certainty","autoGeneratedSummary":"Kevin Warsh has rightly called into question the effectiveness of the Federal Reserve’s communications — but his arrival as chairman only seems to have made the problem worse. To put this right after the next Fed meeting this week, he’ll need to rethink his approach to explaining where things stand.","published":1789380004,"updatedAt":1789380004,"byline":"The Editors","longURL":"https://www.bloomberg.com/opinion/articles/2026-09-14/warsh-and-the-fed-need-clarity-more-than-certainty","primaryCategory":"Editorial Board","wordCount":622,"premium":false}]}]},"status":true,"message":"Successful"}'::jsonb,now(),'Actual upstream HTTP 200 on 2026-09-14; Rust Catalog::build, resolver, input binding and full-response extraction checked.','20260914 RapidAPI news onboarding') ON CONFLICT(id) DO NOTHING;

DO $publish$ DECLARE source_id uuid; source_slug text; expected integer; BEGIN
FOR source_slug, expected IN SELECT * FROM (VALUES ('reuters',4),('bloomberg',1)) v(slug,n) LOOP
 SELECT id INTO STRICT source_id FROM providers.apis WHERE slug=source_slug AND is_platform_owned AND settlement_mode='apiosk_revenue' AND NOT requires_payout_wallet AND listing_type='api' FOR UPDATE;
 IF (SELECT count(*) FROM providers.api_endpoints WHERE api_id=source_id AND active AND price=0.047259)<>expected
  OR (SELECT count(*) FROM catalog.capability_execution_contracts c JOIN providers.api_endpoints e ON e.id=c.endpoint_id WHERE e.api_id=source_id AND c.status IN ('validated','active') AND c.validated_at IS NOT NULL AND c.sample_payload IS NOT NULL)<>expected THEN
  RAISE EXCEPTION '% publication invariant failed',source_slug; END IF;
 PERFORM set_config('apiosk.api_review_approved_id',source_id::text,true);
 UPDATE providers.apis SET status='active',active=true,is_verified=true,discoverable=true,verified_at=coalesce(verified_at,now()),approved_at=coalesce(approved_at,now()),suspended_at=NULL WHERE id=source_id;
 PERFORM set_config('apiosk.api_review_approved_id','',true);
 UPDATE catalog.capability_execution_contracts c SET status='active' FROM providers.api_endpoints e WHERE c.endpoint_id=e.id AND e.api_id=source_id AND c.status='validated';
 IF NOT EXISTS(SELECT 1 FROM providers.apis WHERE id=source_id AND status='active' AND active AND is_verified AND discoverable)
  OR (SELECT count(*) FROM catalog.capability_execution_contracts c JOIN providers.api_endpoints e ON e.id=c.endpoint_id WHERE e.api_id=source_id AND c.status='active')<>expected THEN
  RAISE EXCEPTION '% post-publication invariant failed',source_slug; END IF;
END LOOP; END $publish$;

COMMIT;
